//! C header consistency: `include/linkrs.h` must match the C API sources.
//!
//! The header is generated by cbindgen, but air-gapped builders keep the
//! committed copy (see `build.rs`). This test parses both sides with plain
//! string matching so it runs under default features with no new
//! dependencies, and fails on any drift in either direction:
//! a Rust entry point missing from the header, or a header declaration
//! with no Rust implementation.

use std::collections::BTreeSet;
use std::path::PathBuf;

fn workspace_root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
}

/// Names after `extern "C" fn` in the C API sources.
fn source_functions() -> BTreeSet<String> {
    let dir = workspace_root().join("crates/linkrs-api/src/embedded/c_api");
    let mut names = BTreeSet::new();
    let entries =
        std::fs::read_dir(&dir).unwrap_or_else(|e| panic!("cannot list {}: {e}", dir.display()));
    let mut files: Vec<_> = entries
        .map(|e| e.expect("bad dir entry").path())
        .filter(|p| p.extension().is_some_and(|e| e == "rs"))
        .collect();
    files.sort();
    assert!(
        !files.is_empty(),
        "no C API sources under {}",
        dir.display()
    );
    for path in files {
        let text = std::fs::read_to_string(&path)
            .unwrap_or_else(|e| panic!("cannot read {}: {e}", path.display()));
        for line in text.lines() {
            // Matches `pub unsafe extern "C" fn linkrs_foo(` and the
            // `pub extern "C" fn` variant; unit tests in the same files
            // never use `extern "C"`, so they cannot leak in.
            if let Some(pos) = line.find("extern \"C\" fn linkrs_") {
                let rest = &line[pos + "extern \"C\" fn ".len()..];
                let end = rest
                    .find(|c: char| !c.is_ascii_alphanumeric() && c != '_')
                    .unwrap_or(rest.len());
                names.insert(rest[..end].to_string());
            }
        }
    }
    names
}

/// `linkrs_*` function declarations in the committed header.
///
/// A declaration line starts with a return type at column zero followed by
/// the function name and an opening paren. Type definitions (`typedef
/// struct linkrs_x {`), callback typedefs (`(*linkrs_x_cb)`) and enum
/// variants never match this shape.
fn header_functions() -> BTreeSet<String> {
    let path = workspace_root().join("include/linkrs.h");
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("cannot read {}: {e}", path.display()));
    let mut names = BTreeSet::new();
    for line in text.lines() {
        if line.starts_with(char::is_whitespace) || line.starts_with('#') || line.starts_with('/') {
            continue;
        }
        // A declaration line may mention linkrs_ types before the function
        // name (`struct linkrs_config_t *linkrs_config_new(void);`), so
        // every occurrence is examined, not just the first.
        let bytes = line.as_bytes();
        let mut search = 0;
        while let Some(rel) = line[search..].find("linkrs_") {
            let pos = search + rel;
            search = pos + "linkrs_".len();
            let before = bytes[pos.saturating_sub(1)] as char;
            if !(before == ' ' || before == '*') {
                continue;
            }
            let rest = &line[pos..];
            let end = rest
                .find(|c: char| !c.is_ascii_alphanumeric() && c != '_')
                .unwrap_or(rest.len());
            let name = &rest[..end];
            let after = rest[end..].trim_start();
            if after.starts_with('(')
                && !name.ends_with("_t")
                && !name.ends_with("_cb")
                && !name.contains("callback")
            {
                names.insert(name.to_string());
            }
        }
    }
    names
}

#[test]
fn test_c_header_covers_all_source_entry_points() {
    let src = source_functions();
    let hdr = header_functions();
    assert!(!src.is_empty() && !hdr.is_empty());
    let missing: Vec<_> = src.difference(&hdr).collect();
    assert!(
        missing.is_empty(),
        "C API functions missing from include/linkrs.h: {missing:?}"
    );
}

#[test]
fn test_source_implements_all_header_declarations() {
    let src = source_functions();
    let hdr = header_functions();
    let orphan: Vec<_> = hdr.difference(&src).collect();
    assert!(
        orphan.is_empty(),
        "include/linkrs.h declares functions with no Rust implementation: {orphan:?}"
    );
}
